<?php $rows=qall('SELECT r.*,o.order_code,u.name customer FROM return_requests r JOIN orders o ON o.id=r.order_id JOIN users u ON u.id=r.user_id ORDER BY r.id DESC'); ?>
<section class="erp-card"><div class="erp-card-head"><div><h2>Retur & Penukaran</h2><p>Tinjau pengajuan pelanggan dan perbarui statusnya.</p></div></div><div class="erp-table-wrap"><table><thead><tr><th>Pesanan</th><th>Pelanggan</th><th>Jenis / Alasan</th><th>Status</th><th>Tindakan</th></tr></thead><tbody><?php foreach($rows as $x): ?><tr><td><?= e($x['order_code']) ?></td><td><?= e($x['customer']) ?></td><td><b><?= e($x['request_type']==='return'?'Retur':'Tukar') ?></b><small><?= e($x['reason']) ?></small></td><td><?= e($x['status']) ?></td><td><form method="post" class="erp-form"><input type="hidden" name="action" value="admin_return_status"><input type="hidden" name="csrf" value="<?= e(compliance_csrf()) ?>"><input type="hidden" name="id" value="<?= (int)$x['id'] ?>"><select name="status"><?php foreach(['requested','reviewed','approved','rejected','completed'] as $s): ?><option <?= $x['status']===$s?'selected':'' ?>><?= e($s) ?></option><?php endforeach; ?></select><input name="admin_notes" value="<?= e($x['admin_notes']) ?>" placeholder="Catatan admin"><button class="erp-btn">Update</button></form></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5">Belum ada pengajuan.</td></tr><?php endif; ?></tbody></table></div></section>
